<script setup lang="ts">import { lessons, characters } from '~/data/content'; const route=useRoute(); const lesson=computed(()=>lessons.find(x=>x.day===Number(route.params.id))||lessons[0]); const showPinyin=ref(true); const step=ref(0); const speak=(t:string)=>speechSynthesis.speak(new SpeechSynthesisUtterance(t)); const finish=async()=>{await $fetch(`/api/lessons/${lesson.value.day}/complete`,{method:'POST'}); await navigateTo('/')}</script>
<template><section><div class="page-title"><NuxtLink to="/lessons" class="muted">← Todas as aulas</NuxtLink><h1>Aula {{lesson.day}} · {{lesson.title}}</h1><p class="muted">{{lesson.objective}} · {{lesson.duration}}</p></div><div class="card" style="max-width:850px"><div class="progress"><i :style="{width:((step+1)/3*100)+'%'}"/></div><div v-if="step===0" style="padding:25px 0"><span class="eyebrow">INTRODUÇÃO</span><h2>Vamos começar com uma conversa.</h2><p>Em mandarim, uma saudação simples é <b>你好 (nǐ hǎo)</b>. 你 significa “você” e 好 significa “bem” ou “bom”.</p><button class="button primary" @click="step=1">Ver caracteres →</button></div><div v-else-if="step===1" style="padding:25px 0"><span class="eyebrow">CARACTERES NOVOS</span><div class="grid character-grid" style="margin-top:15px"><div v-for="c in characters.filter(x=>lesson.characters.includes(x.hanzi))" :key="c.hanzi" class="card char-card"><div class="hanzi">{{c.hanzi}}</div><b v-if="showPinyin">{{c.pinyin}}</b><small>{{c.meaning}}</small><button @click="speak(c.pinyin)" class="muted" style="background:none;border:0;margin-top:12px">🔊 ouvir</button></div></div><label style="display:block;margin:18px 0;font-size:13px"><input v-model="showPinyin" type="checkbox"> Mostrar Pinyin</label><button class="button primary" @click="step=2">Fazer exercício →</button></div><div v-else style="padding:25px 0"><span class="eyebrow">EXERCÍCIO</span><h2>Como se diz “você”?</h2><div class="grid" style="grid-template-columns:1fr 1fr;max-width:500px"><button v-for="x in ['你 · nǐ','我 · wǒ','好 · hǎo','他 · tā']" :key="x" class="button" @click="finish">{{x}}</button></div><p class="muted" style="margin-top:20px">Escolha a resposta correta para concluir a aula.</p></div></div></section></template>
